<?php

namespace App\Http\Middleware;

use Closure;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\URL;
use Symfony\Component\HttpFoundation\Response;

/**
 * Forces all URLs generated by Laravel to use the value of APP_URL
 * as the application root. This is required behind proxies (Codespaces,
 * Heroku, Nginx, Cloudflare) where the incoming Host header differs from
 * the public URL. Without this, route() and url() would generate URLs
 * pointing to the internal host (127.0.0.1, localhost, container IP).
 */
class ForceHttpsUrl
{
    public function handle(Request $request, Closure $next): Response
    {
        $appUrl = config('app.url');

        if (is_string($appUrl) && $appUrl !== '') {
            URL::forceRootUrl($appUrl);

            if (str_starts_with($appUrl, 'https://')) {
                URL::forceScheme('https');
            }
        }

        return $next($request);
    }
}
